package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamHumanBodyBank2 {
    private const val T = "මානව දේහ පද්ධතිවල ව්‍යුහය හා ක්‍රියාකාරිත්වය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("අස්ථියක බාහිරින්ම පිහිටා ඇති, රුධිර නාල හා ස්නායුවලින් පොහොසත් අස්ථි ආවරණ පටලය කුමක්ද?", "පෙරියොස්ටියම (Periosteum)", "එන්ඩොස්ටියම", "සයිනෝවියල් පටලය", "මෙනින්ජියම", "පෙරියොස්ටියම මගින් අස්ථිය ආරක්ෂා කරමින් අස්ථි ඝනකමින් වර්ධනය වීමට හා අලුත්වැඩියාවට දායක වේ."),
        q("මිනිස් සිරුරේ රතු රුධිර සෛල, සුදු රුධිර සෛල සහ රුධිර පට්ටිකා නිපදවනු ලබන ප්‍රධාන ස්ථානය කුමක්ද?", "ස්පොන්ජි අස්ථි කුහර තුළ ඇති රතු ඇටමිදුළු", "කහ ඇටමිදුළු", "අක්මාව", "වකුගඩු", "දිගු අස්ථිවල කෙළවර හා පැතලි අස්ථිවල ඇති රතු ඇටමිදුළු තුළ රුධිර සෛල ජනනය (Hematopoiesis) සිදුවේ."),
        q("දිගු අස්ථියක මැද පිහිටි ඇටමිදුළු කුහරයේ (Medullary cavity) ප්‍රධාන වශයෙන් ගබඩා වී ඇත්තේ කුමක්ද?", "මේදය අඩංගු කහ ඇටමිදුළු", "රතු රුධිර සෛල පමණි", "ජලය පමණි", "කැල්සියම් ස්ඵටික පමණි", "කහ ඇටමිදුළු ප්‍රධාන වශයෙන් ඇඩිපෝස් මේද පටකවලින් සමන්විත වන අතර ශක්ති සංචිතයක් ලෙස ක්‍රියා කරයි."),
        q("මිනිස් සිරුරේ අස්ථි පටක අලුතින් ගොඩනැගීමට දායක වන සෛල වර්ගය කුමක්ද?", "ඔස්ටියෝබ්ලාස්ට (Osteoblasts)", "ඔස්ටියෝක්ලාස්ට", "ඔස්ටියෝසයිට", "කොන්ඩ්‍රොසයිට", "ඔස්ටියෝබ්ලාස්ට මගින් කොලැජන් තන්තු නිපදවා කැල්සියම් ඛනිජකරණය මගින් නව අස්ථි පටක තනයි."),
        q("අස්ථි ප්‍රතිසංස්කරණයේදී (Remodeling) පැරණි අස්ථි පටක බිඳහෙළා කැල්සියම් නැවත රුධිරයට අවශෝෂණය කරන සෛල මොනවාද?", "ඔස්ටියෝක්ලාස්ට (Osteoclasts)", "ඔස්ටියෝබ්ලාස්ට", "නියුරෝන", "ලිම්ෆොසයිට", "ඔස්ටියෝක්ලාස්ට මගින් අස්ථි බිඳහෙළා ශරීරයේ කැල්සියම් මට්ටම සමතුලිතව පවත්වා ගනී."),
        q("මිනිස් සිරුරේ කපාල අස්ථි, උරෝස්ථිය සහ අංශ ඵලකය අයත් වන්නේ කුමන හැඩයේ අස්ථි කාණ්ඩයටද?", "පැතලි අස්ථි (Flat Bones)", "දිගු අස්ථි", "කෙටි අස්ථි", "අක්‍රමවත් අස්ථි", "පැතලි අස්ථි මගින් අභ්‍යන්තර අවයව ආරක්ෂා කිරීම සහ පේශි සම්බන්ධ වීමට පුළුල් මතුපිටක් සපයයි."),
        q("කශේරුකා තීරුවේ කශේරුකා අයත් වන්නේ කුමන හැඩයේ අස්ථි වර්ගයටද?", "අක්‍රමවත් අස්ථි (Irregular Bones)", "දිගු අස්ථි", "කෙටි අස්ථි", "සෙසමොයිඩ් අස්ථි", "නිශ්චිත ජ්‍යාමිතික හැඩයක් නොමැති සංකීර්ණ ව්‍යුහයක් සහිත අස්ථි අක්‍රමවත් අස්ථි නම් වේ."),
        q("කණ්ඩරාවක් තුළ තැන්පත් වී ඇති දණහිස් ඇටය (ජානුවස්ථිය) අයත් වන්නේ කුමන විශේෂිත අස්ථි වර්ගයටද?", "සෙසමොයිඩ් අස්ථි (Sesamoid Bones)", "දිගු අස්ථි", "පැතලි අස්ථි", "අක්‍රමවත් අස්ථි", "කණ්ඩරා මත ඇතිවන ඝර්ෂණය හා පීඩනය අවම කිරීම සඳහා කණ්ඩරාව තුළ හටගන්නා අස්ථි සෙසමොයිඩ් අස්ථි වේ."),
        q("සන්ධියකදී අස්ථි දෙක අතර කෝණය අඩු වන සේ අතපය නැවීම හඳුන්වන චලනය කුමක්ද?", "ආකුංචනය (Flexion)", "විස්තාරණය", "අපනයනය", "ආනයනය", "වැලමිට නැවීම හෝ දණහිස නැවීම ආකුංචනය (Flexion) සඳහා නිදසුනකි."),
        q("සන්ධියකදී අස්ථි දෙක අතර කෝණය වැඩි කරමින් අතපය කෙළින් කිරීම හඳුන්වන චලනය කුමක්ද?", "විස්තාරණය (Extension)", "ආකුංචනය", "අපනයනය", "භ්‍රමණය", "නැමුණු වැලමිටක් හෝ දණහිසක් කෙළින් කිරීම විස්තාරණයයි."),
        q("ශරීරයේ මධ්‍ය රේඛාවෙන් ඈතට අතක් හෝ පාදයක් පැත්තට එසවීම හඳුන්වන චලනය කුමක්ද?", "අපනයනය (Abduction)", "ආනයනය", "ආකුංචනය", "විස්තාරණය", "උරහිසෙන් අත පැත්තට එසවීම අපනයනය (Abduction) නම් වේ."),
        q("ශරීරයේ මධ්‍ය රේඛාවෙන් ඈතට ගෙනගිය අතක් හෝ පාදයක් නැවත සිරුර දෙසට ගෙන ඒම හඳුන්වන චලනය කුමක්ද?", "ආනයනය (Adduction)", "අපනයනය", "භ්‍රමණය", "පරිනයනය", "පැත්තට එසවූ අත නැවත ශරීරය දෙසට පහත් කිරීම ආනයනයයි."),
        q("උරහිස් සන්ධියෙන් අත සම්පූර්ණ වෘත්තයක් හෝ කේතුවක හැඩයට කරකැවීම හඳුන්වන චලනය කුමක්ද?", "පරිනයනය (Circumduction)", "භ්‍රමණය පමණි", "ආකුංචනය", "විස්තාරණය", "ආකුංචනය, විස්තාරණය, අපනයනය සහ ආනයනය එකතු වීමෙන් පරිනයනය (Circumduction) සෑදේ."),
        q("අත්ල ඉහළට හෝ ඉදිරියට හරවා තැබීමේ චලනය කුමක්ද?", "උඩුකුරු කිරීම (Supination)", "යටිකුරු කිරීම (Pronation)", "ආකුංචනය", "විස්තාරණය", "අත්ල ඉහළට හරවා ගැනීම සුපිනේෂන් වන අතර බඳුනකින් ජලය පානය කිරීමට අත තබන ඉරියව්වයි."),
        q("අත්ල පහළට හෝ පසුපසට හරවා තැබීමේ චලනය කුමක්ද?", "යටිකුරු කිරීම (Pronation)", "උඩුකුරු කිරීම", "අපනයනය", "භ්‍රමණය", "අරාස්ථිය අන්වරාස්ථිය මතින් හරස් අතට ගමන් කරමින් අත්ල යටිකුරු කිරීම ප්‍රොනේෂන් නම් වේ."),
        q("මාංශපේශී සංකෝචනය පිළිබඳ විද්‍යාත්මකව පිළිගත් 'ලිස්සා යන තන්තු න්‍යාය' (Sliding Filament Theory) අනුව එකිනෙක මත ලිස්සා යන ප්‍රෝටීන් තන්තු දෙක මොනවාද?", "ඇක්ටින් සහ මයොසින් (Actin and Myosin)", "කොලැජන් සහ ඉලාස්ටින්", "කෙරටින් සහ ෆයිබ්‍රින්", "හිමොග්ලොබින් සහ ඇල්බියුමින්", "මයොසින් හිස් ඇක්ටින් තන්තු සමග හරස් පාලම් සාදා ඇක්ටින් තන්තු මධ්‍යය දෙසට ඇදීමෙන් පේශිය සංකෝචනය වේ."),
        q("මාංශපේශී සංකෝචනය ආරම්භ වීම සඳහා සාර්කොප්ලාස්මික ජාලයෙන් මුදාහැරිය යුතු අත්‍යවශ්‍ය ඛනිජ අයනය කුමක්ද?", "කැල්සියම් අයන (Ca2+)", "සෝඩියම් අයන", "පොටෑසියම් අයන", "යකඩ අයන", "කැල්සියම් අයන ට්‍රොපොනින් සමග බැඳීමෙන් ඇක්ටින් මත ඇති මයොසින් බන්ධන ස්ථාන විවෘත වේ."),
        q("මාංශපේශී සංකෝචනයට සහ ලිහිල් වීමට අවශ්‍ය සෛලීය ශක්තිය සපයන රසායනික අණුව කුමක්ද?", "ඇඩිනොසින් ට්‍රයිපොස්පේට් (ATP)", "ග්ලූකෝස් පමණි", "ලැක්ටික් අම්ලය", "DNA", "ATP ජලවිච්ඡේදනයෙන් ලැබෙන ශක්තිය මගින් මයොසින් හරස් පාලම් චලනය වීම සිදුවේ."),
        q("මයෝග්ලොබින් සහ මයිටොකොන්ඩ්‍රියා බහුල, සෙමින් සංකෝචනය වන, තෙහෙට්ටුවට ඔරොත්තු දෙන රතු පේශි තන්තු වර්ගය කුමක්ද?", "මන්ද සංකෝචී තන්තු (Slow-twitch / Type I fibers)", "ක්ෂණික සංකෝචී තන්තු", "සුදු පේශි තන්තු", "අනෛච්ඡික තන්තු", "මන්ද සංකෝචී රතු තන්තු මැරතන් ධාවනය වැනි දීර්ඝ විඳදරාගැනීමේ ක්‍රීඩා සඳහා වඩාත් යෝග්‍ය වේ."),
        q("නිර්වායු ශ්වසනය මත යැපෙන, ඉතා වේගයෙන් හා ප්‍රබලව සංකෝචනය වන නමුත් ඉක්මනින් තෙහෙට්ටුවට පත්වන සුදු පේශි තන්තු කුමක්ද?", "ක්ෂණික සංකෝචී තන්තු (Fast-twitch / Type II fibers)", "මන්ද සංකෝචී තන්තු", "රතු තන්තු", "හෘත් තන්තු", "මීටර් 100 කෙටි දුර ධාවනය හා බර එසවීම සඳහා ක්ෂණික සංකෝචී සුදු තන්තු ප්‍රධාන වේ."),
        q("තනි චාලක නියුරෝනයක් සහ එයින් ස්නායුනය වන මාංශපේශී තන්තු සමූහය එක්ව හඳුන්වන්නේ කෙසේද?", "මෝටර් ඒකකය (Motor Unit)", "ස්නායු සන්ධිය", "ප්‍රතිචාර චාපය", "සාර්කොමියරය", "සියුම් චලන පාලනය කරන පේශිවල (ඇසේ පේශි) කුඩා මෝටර් ඒකකද විශාල බලයක් දෙන පේශිවල විශාල මෝටර් ඒකකද ඇත."),
        q("මිනිස් හෘදයේ ස්වාභාවික රිද්මකාරකය (ස්වාභාවික පේස්මේකරය) ලෙස ක්‍රියා කරමින් විද්‍යුත් ආවේග ආරම්භ කරන ස්ථානය කුමක්ද?", "සයිනෝ-කර්ණික ගැටය (SA Node)", "කර්ණික-කෝෂික ගැටය (AV Node)", "හිස්ගේ කදම්භය", "පර්කින්ජි තන්තු", "දකුණු කර්ණික බිත්තියේ පිහිටි SA ගැටය මිනිත්තුවකට වාර 70-80ක් පමණ ස්වයංක්‍රීයව විද්‍යුත් සංඥා ජනනය කරයි."),
        q("SA ගැටයෙන් එන විද්‍යුත් ආවේගය තත්පරයකින් දශමයක පමණ ප්‍රමාදයකට ලක් කර කෝෂිකා වෙත යවන හෘදයේ ගැටය කුමක්ද?", "කර්ණික-කෝෂික ගැටය (AV Node)", "සයිනෝ-කර්ණික ගැටය", "පර්කින්ජි තන්තු", "මහා ධමනි කපාටය", "AV ගැටයේදී සිදුවන සුළු ප්‍රමාදය නිසා කර්ණිකා සම්පූර්ණයෙන් හැකිලී කෝෂිකා පිරෙන තෙක් කෝෂිකා හැකිලීම වැළකේ."),
        q("හෘදයේ විද්‍යුත් ක්‍රියාකාරිත්වය ප්‍රස්තාරගත කර හඳුනාගැනීම සඳහා යොදාගන්නා පරීක්ෂණය කුමක්ද?", "විද්‍යුත් හෘද රේඛනය (ECG / EKG)", "විද්‍යුත් නිල රේඛනය (EEG)", "MRI පරීක්ෂණය", "CT ස්කෑන් පරීක්ෂණය", "ECG ප්‍රස්තාරයේ P තරංගය, QRS සංකීර්ණය සහ T තරංගය මගින් හෘදයේ සංකෝචන හා ලිහිල්වීම් නිරූපණය වේ."),
        q("නිරෝගී මිනිස් හෘද චක්‍රයක් (Cardiac Cycle) සම්පූර්ණ වීමට ගතවන සාමාන්‍ය කාලය තත්පර කීයක්ද?", "තත්පර 0.8කි", "තත්පර 2.0කි", "තත්පර 5.0කි", "තත්පර 0.1කි", "කර්ණික සිස්ටෝලය (0.1s), කෝෂික සිස්ටෝලය (0.3s) සහ සම්පූර්ණ හෘද ඩයස්ටෝලය (0.4s) එකතු වී තත්පර 0.8ක් වේ."),
        q("හෘද ස්පන්දනයකදී ස්ටෙතස්කෝපයකින් ඇසෙන පළමු ශබ්දය වන 'ලබ්' (Lub) ශබ්දය ඇතිවන්නේ කුමන හේතුව නිසාද?", "කර්ණික-කෝෂික කපාට (ද්විතුණ්ඩ හා ත්‍රිතුණ්ඩ) එකවර වැසී යාම නිසා", "අඩසඳ කපාට වැසීම නිසා", "රුධිරය පෙනහළුවලට ගලායාම නිසා", "හදවත ගැහීම නිසා", "කෝෂිකා හැකිලීම ආරම්භයේදී ද්විතුණ්ඩ හා ත්‍රිතුණ්ඩ කපාට වැසී යාමෙන් පළමු ශබ්දය උපදී."),
        q("හෘදයේ දෙවන ශබ්දය වන කෙටි තියුණු 'ඩබ්' (Dub) ශබ්දය ජනනය වන්නේ කුමන ක්‍රියාවලියෙන්ද?", "මහා ධමනි සහ පුප්ඵුසීය අඩසඳ කපාට වැසී යාම නිසා", "කර්ණිකා හැකිලීම නිසා", "ද්විතුණ්ඩ කපාට විවෘත වීම නිසා", "හෘද පේශිය ලිහිල් වීම නිසා", "කෝෂිකා ලිහිල් වීම ආරම්භයේදී අඩසඳ කපාට තදින් වැසී යාමෙන් දෙවන හෘද ශබ්දය ඇතිවේ."),
        q("එක් හෘද ස්පන්දනයකදී එක් කෝෂිකාවකින් ධමනි තුළට පොම්ප කරනු ලබන රුධිර පරිමාව හඳුන්වන්නේ කෙසේද?", "පහර පරිමාව (Stroke Volume)", "හෘද නිමැවුම", "උදම් පරිමාව", "ජෛව ධාරිතාව", "විවේකීව සිටින වැඩිහිටියෙකුගේ සාමාන්‍ය පහර පරිමාව මිලිලීටර් 70ක් (70 ml) පමණ වේ."),
        q("එක් මිනිත්තුවක් තුළදී එක් කෝෂිකාවකින් පොම්ප කරන මුළු රුධිර පරිමාව හඳුන්වන නම කුමක්ද?", "හෘද නිමැවුම (Cardiac Output)", "පහර පරිමාව", "රුධිර පීඩනය", "ප්ලාස්මා පරිමාව", "හෘද නිමැවුම = පහර පරිමාව × හෘද ස්පන්දන වේගය (70 ml × 72 bpm ≈ මිනිත්තුවට ලීටර් 5ක්)."),
        q("දැඩි ව්‍යායාමයකදී ක්‍රීඩකයෙකුගේ හෘද නිමැවුම මිනිත්තුවට ලීටර් 5 සිට සාමාන්‍යයෙන් කොපමණ දක්වා ඉහළ යා හැකිද?", "මිනිත්තුවට ලීටර් 20 සිට 30 දක්වා", "මිනිත්තුවට ලීටර් 100 දක්වා", "මිනිත්තුවට ලීටර් 7 දක්වා පමණි", "වෙනස් නොවේ", "ව්‍යායාමයේදී පහර පරිමාව සහ ස්පන්දන වේගය දෙකම වැඩිවීම නිසා හෘද නිමැවුම 5-6 ගුණයකින් ඉහළ යයි."),
        q("මිනිස් රුධිරයේ ඔක්සිජන් වැඩිම ප්‍රමාණයක් (98.5% ක් පමණ) සිරුර පුරා පරිවහනය වන්නේ කුමන ආකාරයෙන්ද?", "රතු රුධිරාණුවල හිමොග්ලොබින් සමග බැඳී ඔක්සිහිමොග්ලොබින් ලෙස", "ප්ලාස්මාවේ දියවී", "සුදු රුධිරාණු තුළ", "බයිකාබනේට් අයන ලෙස", "පෙනහළුවලදී හිමොග්ලොබින් ඔක්සිජන් සමග ප්‍රතිවර්ත්‍ය ලෙස බැඳී ඔක්සිහිමොග්ලොබින් තනයි."),
        q("පටකවලින් නිපදවන කාබන් ඩයොක්සයිඩ් (CO2) වැඩිම ප්‍රමාණයක් (70% ක් පමණ) රුධිරය ඔස්සේ පරිවහනය වන්නේ කුමන ස්වරූපයෙන්ද?", "ප්ලාස්මාවේ බයිකාබනේට් අයන (HCO3-) ලෙස", "කාබොක්සිහිමොග්ලොබින් ලෙස", "වායු බුබුළු ලෙස", "ග්ලූකෝස් සමග බැඳී", "රතු රුධිර සෛල තුළ ඇති කාබොනික් ඇන්හයිඩ්‍රේස් එන්සයිමය මගින් CO2 බයිකාබනේට් බවට පත් කරයි."),
        q("වාතයේ ඇති කාබන් මොනොක්සයිඩ් (CO) වායුව ආශ්වාස කිරීම මාරාන්තික අනතුරක් වන්නේ කුමන හේතුව නිසාද?", "හිමොග්ලොබින් සමග ඔක්සිජන් මෙන් 200 ගුණයකට වඩා ප්‍රබලව බැඳී ඔක්සිජන් පරිවහනය අඩාල කරන බැවින්", "එය ඇස් අන්ධ කරන බැවින්", "එය උගුරේ සෙම හිරකරන බැවින්", "එය ආහාර ජීර්ණය නවත්වන බැවින්", "කාබන් මොනොක්සයිඩ් හිමොග්ලොබින් සමග කාබොක්සිහිමොග්ලොබින් නම් ස්ථාවර සංයෝගය සාදා පටකවලට ඔක්සිජන් නොලැබී මරණය ඇති කරයි."),
        q("මිනිස් ශ්වසන වේගය ප්‍රධාන වශයෙන් පාලනය කරනු ලබන්නේ රුධිරයේ කුමන සංඝටකයේ සාන්ද්‍රණය ඉහළ යාම මගින්ද?", "කාබන් ඩයොක්සයිඩ් (CO2) සහ H+ අයන සාන්ද්‍රණය ඉහළ යාම", "ඔක්සිජන් අඩුවීම පමණි", "ග්ලූකෝස් වැඩිවීම", "නයිට්‍රජන් වැඩිවීම", "රුධිරයේ CO2 වැඩි වන විට මොළයේ ශ්වසන මධ්‍යස්ථානය උත්තේජනය වී ශ්වසන වේගය වැඩි කරයි."),
        q("මිනිස් සිරුරේ ස්නායු පද්ධතියේ මූලික ව්‍යුහාත්මක හා ක්‍රියාකාරී ඒකකය කුමක්ද?", "නියුරෝනය හෙවත් ස්නායු සෛලය (Neuron)", "නෙෆ්‍රෝනය", "ඇක්සෝනය", "මයෝෆයිබ්‍රිලය", "නියුරෝන මගින් විද්‍යුත්-රසායනික සංඥා සම්ප්‍රේෂණය කරමින් සිරුරේ පාලනය හා සම්බන්ධීකරණය සිදු කරයි."),
        q("නියුරෝනයක සෛල දේහය දෙසට ආවේග රැගෙන එන අතු බෙදුණු කෙටි ප්‍රසර මොනවාද?", "ඩෙන්ඩ්‍රයිට (Dendrites)", "ඇක්සෝනය", "මයිලින් කොපුව", "රැන්වියර් ගැටය", "ඩෙන්ඩ්‍රයිට මගින් උත්තේජන හෝ වෙනත් නියුරෝනවලින් සංඥා ලබාගෙන සෛල දේහයට යොමු කරයි."),
        q("නියුරෝනයක සෛල දේහයේ සිට ආවේගය ඉවතට රැගෙන යන තනි දිගු ප්‍රසරය කුමක්ද?", "ඇක්සෝනය (Axon)", "ඩෙන්ඩ්‍රයිටය", "න්‍යෂ්ටිය", "සිනැප්සිය", "ඇක්සෝනය ඔස්සේ විද්‍යුත් ආවේගය වෙනත් නියුරෝනයක් හෝ පේශියක් දෙසට ගමන් කරයි."),
        q("ස්නායු තන්තුවක් ආවරණය කරමින් ආවේග ගමන් කිරීමේ වේගය කිහිප ගුණයකින් වැඩි කරන මේදමය පරිවාරක ස්ථරය කුමක්ද?", "මයිලින් කොපුව (Myelin Sheath)", "පෙරියොස්ටියම", "මෙනින්ජියම", "ප්ලූරාව", "මයිලින් කොපුව ෂ්වාන් සෛල මගින් සෑදෙන අතර ආවේග පැන පැන (Saltatory conduction) වේගයෙන් ගමන් කිරීමට ඉඩ සලසයි."),
        q("ස්නායු නියුරෝන දෙකක් එකිනෙක මුණගැසෙන සියුම් අන්වීක්ෂීය සන්ධිය හඳුන්වන්නේ කෙසේද?", "ස්නායු සන්ධිය හෙවත් සිනැප්සිය (Synapse)", "මෝටර් ඒකකය", "සයිනෝවියල් කුහරය", "මැහුම් සන්ධිය", "සිනැප්සියේදී විද්‍යුත් සංඥාව රසායනික සම්ප්‍රේෂක මගින් ඊළඟ නියුරෝනයට සම්ප්‍රේෂණය වේ."),
        q("ස්නායු සන්ධියක් හරහා ආවේගයක් සම්ප්‍රේෂණය කිරීමට නිකුත් වන රසායනික ද්‍රව්‍යයක් කුමක්ද?", "ස්නායු සම්ප්‍රේෂකය (උදා. ඇසිටයිල්කොලීන්)", "ඉන්සියුලින්", "හිමොග්ලොබින්", "තයිරොක්සින්", "ඇසිටයිල්කොලීන් (ACh) සහ ඩොපමයින් වැනි ස්නායු සම්ප්‍රේෂක මගින් ආවේග සම්ප්‍රේෂණය කෙරේ."),
        q("හදිසි බියකදී, අනතුරකදී හෝ දැඩි තරගකාරී අවස්ථාවකදී 'සටන් කිරීම හෝ පලායාම' (Fight or Flight) සඳහා සිරුර සූදානම් කරන හෝමෝනය කුමක්ද?", "ඇඩ්‍රිනලින් (Adrenaline / Epinephrine)", "ඉන්සියුලින්", "තයිරොක්සින්", "ඊස්ට්‍රජන්", "ඇඩ්‍රිනලින් මගින් හෘද ස්පන්දනය, රුධිර පීඩනය හා රුධිර ග්ලූකෝස් මට්ටම ක්ෂණිකව ඉහළ නංවයි."),
        q("පිරිමි ද්විතීයික ලිංගික ලක්ෂණ පහළ වීමට සහ මාංශපේශී ස්කන්ධය වර්ධනය වීමට බලපාන ප්‍රධාන පිරිමි හෝමෝනය කුමක්ද?", "ටෙස්ටොස්ටෙරෝන් (Testosterone)", "ඊස්ට්‍රජන්", "ප්‍රොජෙස්ටරෝන්", "ප්‍රෝලැක්ටින්", "වෘෂණවලින් ශ්‍රාවය වන ටෙස්ටොස්ටෙරෝන් හෝමෝනය පේශි වර්ධනය හා අස්ථි ඝනකමට බෙහෙවින් දායක වේ."),
        q("කාන්තා ද්විතීයික ලිංගික ලක්ෂණ පහළ වීම සහ ඔසප් චක්‍රය නියාමනය කරන ප්‍රධාන ඩිම්බකෝෂ හෝමෝන යුගලය කුමක්ද?", "ඊස්ට්‍රජන් සහ ප්‍රොජෙස්ටරෝන්", "ටෙස්ටොස්ටෙරෝන් සහ ඉන්සියුලින්", "තයිරොක්සින් සහ ඇඩ්‍රිනලින්", "ග්ලුකොගන් සහ ඔක්සිටොසින්", "ඩිම්බකෝෂ මගින් නිපදවන ඊස්ට්‍රජන් හා ප්‍රොජෙස්ටරෝන් මගින් ප්‍රජනක පද්ධතිය පාලනය කරයි."),
        q("මිනිස් සිරුරේ අනෙකුත් සියලුම අන්තරාසර්ග ග්‍රන්ථිවල ක්‍රියාකාරිත්වය පාලනය කරන ප්‍රධානතම 'මහ ග්‍රන්ථිය' (Master Gland) කුමක්ද?", "පිටියුටරි ග්‍රන්ථිය (Pituitary Gland)", "තයිරොයිඩ් ග්‍රන්ථිය", "අධිවෘක්ක ග්‍රන්ථිය", "අග්න්‍යාසය", "මොළයේ පාදමේ පිහිටි පිටියුටරි ග්‍රන්ථිය මගින් අනෙක් ග්‍රන්ථි උත්තේජනය කරන ට්‍රොපික හෝමෝන නිදහස් කරයි."),
        q("මිනිස් සිරුරේ උෂ්ණත්වය සෙල්සියස් අංශක 37 ක නියත මට්ටමක පවත්වා ගන්නා මොළයේ ප්‍රධාන උෂ්ණත්ව නියාමක මධ්‍යස්ථානය කුමක්ද?", "හයිපොතලමස (Hypothalamus)", "මස්තිෂ්කය", "අනුමස්තිෂ්කය", "සුෂුම්නාව", "හයිපොතලමස සිරුරේ උෂ්ණත්වය වැඩි වූ විට දහඩිය දැමීමද අඩු වූ විට වෙව්ලීමද උත්තේජනය කරයි."),
        q("සීතල පරිසරයකදී ශරීරයේ තාපය ආරක්ෂා කර ගැනීම සඳහා සමේ ඇති රුධිර කේශනාලිකා හැකිලී යාමේ ක්‍රියාවලිය කුමක්ද?", "වාහිනී සංකෝචනය (Vasoconstriction)", "වාහිනී විස්තාරණය", "දහඩිය දැමීම", "ශ්වසනය වේගවත් වීම", "රුධිර වාහිනී හැකිලීම මගින් සම මතුපිටින් සිදුවන තාප විකිරණය අවම කරයි."),
        q("අධික රස්නයක් සහිත පරිසරයකදී සිරුර සිසිල් කිරීම සඳහා සමේ රුධිර නාල පුළුල් වී රතු පැහැවීම හඳුන්වන්නේ කෙසේද?", "වාහිනී විස්තාරණය (Vasodilation)", "වාහිනී සංකෝචනය", "වෙව්ලීම", "අංශභාගය", "රුධිර වාහිනී විස්තාරණය වීමෙන් සම මතුපිටට වැඩි රුධිර ප්‍රමාණයක් ගලා විත් තාපය පරිසරයට මුදාහරියි."),
        q("නිරෝගී මිනිස් දේහයේ සාමාන්‍ය අභ්‍යන්තර උෂ්ණත්වය සෙල්සියස් අංශක කීයක් ලෙස සැලකේද?", "සෙල්සියස් අංශක 37.0ක් (37°C)", "සෙල්සියස් අංශක 30.0ක්", "සෙල්සියස් අංශක 40.0ක්", "සෙල්සියස් අංශක 25.0ක්", "සාමාන්‍ය ශරීර උෂ්ණත්වය 36.5°C - 37.5°C (98.6°F) පරාසයේ නියතව පවත්වා ගනී."),
        q("මිනිස් පෙනහළු ආවරණය කරමින් ආරක්ෂා කරන ද්විත්ව පටලමය ආවරණය කුමක්ද?", "ප්ලූරල් පටලය (Pleura)", "පෙරිකාඩියම", "මෙනින්ජියම", "පෙරිටෝනියම", "ප්ලූරා පටල දෙක අතර ඇති ප්ලූරල් තරලය මගින් ශ්වසනයේදී පෙනහළු හා උරස් බිත්තිය අතර ඝර්ෂණය වළක්වයි."),
        q("මිනිස් හදවත ආවරණය කරමින් කම්පනවලින් ආරක්ෂා කරන තරල පිරි ද්විත්ව පටලය කුමක්ද?", "පෙරිකාඩියම (Pericardium)", "ප්ලූරාව", "පෙරියොස්ටියම", "එන්ඩොකාඩියම", "පෙරිකාඩියල් තරලය මගින් හෘදය ස්පන්දනය වීමේදී ඇතිවන ඝර්ෂණය අවම කරයි."),
        q("මොළය සහ සුෂුම්නාව බාහිර කම්පනවලින් ආරක්ෂා කරමින් ආවරණය කර ඇති ත්‍රිත්ව පටල පද්ධතිය කුමක්ද?", "මෙනින්ජි පටල (Meninges)", "ප්ලූරාව", "පෙරිකාඩියම", "පෙරිටෝනියම", "ඩියුරා මාතාව, ඇරක්නොයිඩය සහ පියා මාතාව යන පටල තුන මොළය වටා පිහිටයි."),
        q("මොළයේ කෝෂිකා සහ සුෂුම්නාවේ මධ්‍ය නාලය තුළ ගලා යන, පෝෂණය හා කම්පන ආරක්ෂාව සපයන තරලය කුමක්ද?", "මස්තිෂ්ක සුෂුම්නා තරලය (CSF)", "සයිනෝවියල් තරලය", "ප්ලූරල් තරලය", "වසා තරලය", "Cerebrospinal Fluid මොළය සැහැල්ලු කරමින් කම්පනවලින් සහ විෂබීජවලින් මොළය ආරක්ෂා කරයි."),
        q("ශරීරයේ ඇති ප්‍රධාන වසා අවයවයක් වන, පැරණි රතු රුධිරාණු විනාශ කරන සහ රුධිරය ගබඩා කර තබන අවයවය කුමක්ද?", "ප්ලීහාව (Spleen)", "අක්මාව", "පිත්තාශය", "අග්න්‍යාසය", "ප්ලීහාව ශරීරයේ රුධිර පෙරහනක් ලෙස ක්‍රියා කරමින් හානි වූ රතු සෛල විනාශ කර ප්‍රතිශක්තිය ලබා දෙයි."),
        q("ළමා වියේදී පපුවේ ඉහළ ප්‍රදේශයේ පිහිටා ඇති, T-ලිම්ෆොසයිට සෛල පරිණත කිරීමට දායක වන ප්‍රතිශක්තිකරණ ග්‍රන්ථිය කුමක්ද?", "තයිමස් ග්‍රන්ථිය (Thymus Gland)", "තයිරොයිඩ් ග්‍රන්ථිය", "පිටියුටරි ග්‍රන්ථිය", "අධිවෘක්ක ග්‍රන්ථිය", "තයිමස් ග්‍රන්ථිය ළමා වියේදී ඉතා ක්‍රියාකාරී වන අතර වැඩිහිටි වියට පත්වත්ම ක්‍රමයෙන් ක්ෂය වී යයි."),
        q("මිනිස් සිරුරේ ස්වයංසාධක ස්නායු පද්ධතියේ ප්‍රධාන ශාඛා දෙක මොනවාද?", "අනුකම්පී සහ ප්‍රත්‍යානුකම්පී ස්නායු පද්ධති", "මධ්‍ය හා පර්යන්ත පද්ධති", "සංවේදක හා චාලක පද්ධති", "ඓච්ඡික හා අචල පද්ධති", "අනුකම්පී පද්ධතිය සිරුර සක්‍රීය කරන අතර ප්‍රත්‍යානුකම්පී පද්ධතිය සිරුර විවේකී කරවයි."),
        q("හෘද ස්පන්දනය වේගවත් කිරීම, ශ්වාසනාලිකා විස්තාරණය කිරීම සහ ආහාර ජීර්ණය අඩාල කිරීම සිදුකරන ස්නායු පද්ධතිය කුමක්ද?", "අනුකම්පී ස්නායු පද්ධතිය (Sympathetic Nervous System)", "ප්‍රත්‍යානුකම්පී පද්ධතිය", "මධ්‍ය ස්නායු පද්ධතිය", "සෝමාටික පද්ධතිය", "හදිසි අවස්ථාවලදී ක්‍රියාත්මක වී ශරීරයේ ශක්තිය වැය කිරීමට අනුකම්පී පද්ධතිය මඟ පාදයි."),
        q("හෘද ස්පන්දනය මන්දගාමී කිරීම, ආහාර ජීර්ණය උත්තේජනය කිරීම සහ සිරුර විවේකී කරවීම සිදුකරන ස්නායු පද්ධතිය කුමක්ද?", "ප්‍රත්‍යානුකම්පී ස්නායු පද්ධතිය (Parasympathetic Nervous System)", "අනුකම්පී පද්ධතිය", "චාලක පද්ධතිය", "බාහිර පද්ධතිය", "විවේකී හා සන්සුන් අවස්ථාවලදී ප්‍රත්‍යානුකම්පී පද්ධතිය මගින් ශරීර ශක්තිය සංරක්ෂණය කරයි."),
        q("ක්‍රීඩාවේදී නිරන්තරයෙන් සිදුවන ආශ්වාස ප්‍රශ්වාස ක්‍රියාවලිය කාර්යක්ෂම කිරීමට ඉළඇට අතර පිහිටි පේශි හඳුන්වන්නේ කෙසේද?", "අන්තර්-ඉළඇට පේශි (Intercostal Muscles)", "පෙක්ටොරාලිස් පේශි", "ඩෙල්ටොයිඩ් පේශි", "ලැටිසිමස් ඩෝසි", "බාහිර හා අභ්‍යන්තර අන්තර්-ඉළඇට පේශි මගින් ඉළඇට කූඩුව ඉහළට හා පහළට චලනය කරයි."),
        q("ශරීරයේ ඇති ප්‍රධානතම ස්වේච්ඡා නොවන හුස්ම ගැනීමේ මාංශපේශී ප්‍රාචීරය උරස් කුහරය වෙන් කරන්නේ කුමන කුහරයෙන්ද?", "උදර කුහරයෙන් (Abdominal Cavity)", "කපාල කුහරයෙන්", "ශ්‍රෝණි කුහරයෙන්", "හෘද කුහරයෙන්", "මහා ප්‍රාචීරය උරස් කුහරය සහ උදර කුහරය එකිනෙකින් වෙන් කරන ගෝලාකාර පේශිමය බිත්තියයි."),
        q("මිනිස් සිරුරේ ප්‍රධානතම විෂහරණ (Detoxification) අවයවය ලෙස රුධිරයේ ඇති විෂ ද්‍රව්‍ය හා ඖෂධ අක්‍රිය කරන්නේ කුමන ඉන්ද්‍රිය මගින්ද?", "අක්මාව (Liver)", "වකුගඩු", "පෙනහළු", "ප්ලීහාව", "අක්මාව මගින් ඇල්කොහොල්, බැර ලෝහ හා ඖෂධ විෂහරණය කර අහිතකර බලපෑම් වළක්වයි."),
        q("දිනපතා නිතිපතා aerobic ව්‍යායාමවල යෙදීමෙන් හෘද වාහිනී පද්ධතියට ලැබෙන වාසිදායක දිගුකාලීන අනුවර්තනයක් කුමක්ද?", "වම් කෝෂිකාවේ පරිමාව හා පහර පරිමාව වැඩි වී විවේකී හෘද ස්පන්දන වේගය අඩුවීම", "රුධිර නාල දැඩි වී රුධිර පීඩනය ඉහළ යාම", "හෘද පේශිය දුර්වල වීම", "පෙනහළු පරිමාව ක්ෂය වීම", "නිතිපතා ව්‍යායාම මගින් හෘදය ශක්තිමත් වී අඩු වෙහෙසකින් වැඩි රුධිර ප්‍රමාණයක් පොම්ප කිරීමට සමත් වේ."),
        q("මිනිස් සිරුරේ ජෛව ඔරලෝසුව හෙවත් නින්ද සහ අවදිවීමේ චක්‍රය පාලනය කරන මෙලටොනින් හෝමෝනය නිපදවන ග්‍රන්ථිය කුමක්ද?", "පීනියල් ග්‍රන්ථිය (Pineal Gland)", "තයිරොයිඩ් ග්‍රන්ථිය", "තයිමස් ග්‍රන්ථිය", "අධිවෘක්ක ග්‍රන්ථිය", "මොළයේ මධ්‍යයේ පිහිටි පීනියල් ග්‍රන්ථිය අඳුර හමුවේ මෙලටොනින් නිපදවා සුව නින්දක් ලබාදෙයි."),
        q("වකුගඩුවල ඉහළ කෙළවරේ තොප්පියක් මෙන් පිහිටා ඇති කෝටිසෝල් සහ ඇඩ්‍රිනලින් නිපදවන ග්‍රන්ථිය කුමක්ද?", "අධිවෘක්ක ග්‍රන්ථිය (Adrenal Gland)", "පිටියුටරි ග්‍රන්ථිය", "තයිරොයිඩ් ග්‍රන්ථිය", "පැරාතයිරොයිඩ් ග්‍රන්ථිය", "අධිවෘක්ක බාහිකයෙන් කෝටිසෝල් සහ ඇල්ඩොස්ටෙරෝන්ද මජ්ජාවෙන් ඇඩ්‍රිනලින්ද ශ්‍රාවය වේ."),
        q("රුධිරයේ කැල්සියම් මට්ටම පහත වැටුණු විට අස්ථිවලින් කැල්සියම් නිදහස් කර රුධිර කැල්සියම් මට්ටම ඉහළ නංවන හෝමෝනය කුමක්ද?", "පැරතොමෝනය (PTH)", "කැල්සිටොනින්", "තයිරොක්සින්", "ඉන්සියුලින්", "පැරාතයිරොයිඩ් ග්‍රන්ථියෙන් ශ්‍රාවය වන පැරතොමෝනය මගින් රුධිරයේ කැල්සියම් ප්‍රමාණය නියතව තබා ගනී."),
        q("රුධිරයේ කැල්සියම් මට්ටම අධික වූ විට අස්ථි තුළ කැල්සියම් තැන්පත් කරවීම උත්තේජනය කරන හෝමෝනය කුමක්ද?", "කැල්සිටොනින් (Calcitonin)", "පැරතොමෝනය", "ග්ලුකොගන්", "ඇඩ්‍රිනලින්", "තයිරොයිඩ් ග්‍රන්ථියෙන් නිකුත් වන කැල්සිටොනින් මගින් අස්ථිවලට කැල්සියම් අවශෝෂණය වැඩි කරයි."),
        q("මිනිස් සිරුරේ අස්ථි බන්ධනී (Ligaments) සෑදී ඇත්තේ ප්‍රධාන වශයෙන් කුමන ප්‍රෝටීනයෙන්ද?", "කොලැජන් සහ ඉලාස්ටින් තන්තු", "කෙරටින්", "ඇක්ටින්", "මයොසින්", "කොලැජන් මගින් ශක්තියද ඉලාස්ටින් මගින් යම් ප්‍රත්‍යාස්ථතාවක්ද බන්ධනීවලට ලබා දෙයි."),
        q("මිනිස් අක්ෂි ගෝලයේ ආලෝකය සංවේදනය කරන රොඩ් සහ කෝන් සෛල පිහිටා ඇති අභ්‍යන්තර ස්ථරය කුමක්ද?", "දෘෂ්ටිවිතානය (Retina)", "කෝනියාව", "දේහිකාව", "සුදුඉංගිරියාව", "දෘෂ්ටිවිතානයේ රොඩ් සෛල අඳුරටද කෝන් සෛල වර්ණ ආලෝකයටද සංවේදී වේ."),
        q("මිනිස් කනේ ශ්‍රවණය සඳහා දායක වන කර්ණ අස්ථිකා ත්‍රිත්වය නිවැරදිව දැක්වෙන පිළිතුර කුමක්ද?", "අභිඝාතිය (Malleus), නිඝාතිය (Incus) සහ අඩිකලය (Stapes)", "ඇට්ලස්, ඇක්සිස් සහ කශේරුකාව", "අරාස්ථිය, අන්වරාස්ථිය සහ ප්‍රගණ්ඩාස්ථිය", "කලවාස්ථිය, ජානුවස්ථිය සහ අන්වස්ථාස්ථිය", "මධ්‍ය කනේ ඇති මෙම අස්ථිකා තුන කන් බෙරයේ කම්පන ඇතුල් කන වෙත විශාලනය කර යවයි."),
        q("මිනිස් සිරුරේ ඇති කුඩාම අස්ථිය වන අඩිකලය (Stapes) පිහිටා ඇත්තේ කොහේද?", "මධ්‍ය කන තුළ", "නාසා කුහරයේ", "ඇඟිලි තුඩුවල", "ඇස තුළ", "අඩිකල අස්ථිය සහල් ඇටයකට වඩා කුඩා වන අතර මධ්‍ය කනේ ඉලිප්සාකාර කවුළුව මත පිහිටයි."),
        q("කනේ අභ්‍යන්තරයේ පිහිටා ඇති හිසේ සහ ශරීරයේ චලනයන් හඳුනාගෙන සමබරතාවය පවත්වා ගැනීමට උපකාරී වන ව්‍යුහය කුමක්ද?", "අර්ධ චක්‍රාකාර නාල (Semicircular Canals)", "කර්ණ ශංඛය", "කන් බෙරය", "යුස්ටේකීය නාලය", "අර්ධ චක්‍රාකාර නාල තුළ ඇති තරලයේ චලනය මගින් ගතික සමබරතාව මොළයට දන්වයි."),
        q("ගිලීමේදී හෝ කිවිසුම් යැවීමේදී කන් බෙරයේ දෙපස වායු පීඩනය සමාන කිරීමට උපකාරී වන නාලය කුමක්ද?", "යුස්ටේකීය නාලය (Eustachian Tube)", "අර්ධ චක්‍රාකාර නාලය", "කර්ණ නාලය", "ස්වරාලය", "යුස්ටේකීය නාලය මධ්‍ය කන සහ ග්‍රසනිකාව එකිනෙක සම්බන්ධ කරයි."),
        q("මිනිස් සිරුරේ අස්ථි එකිනෙක සම්බන්ධ කරන ප්‍රධාන කෘචස්ථි වර්ගය වන දිගු අස්ථි කෙළවර පිහිටි කෘචස්ථිය කුමක්ද?", "හයලින් කෘචස්ථිය (Hyaline Cartilage)", "ප්‍රත්‍යාස්ථ කෘචස්ථිය", "තන්තුමය කෘචස්ථිය", "අස්ථිමය පටකය", "හයලින් කාටිලේජය ඉතා සිනිඳු වන අතර සන්ධිවල ඝර්ෂණය අවම කිරීමට උපකාරී වේ."),
        q("බාහිර කන් පෙත්ත සහ එපිග්ලොටිසය (උපජිහ්විකාව) සෑදී ඇත්තේ කුමන නම්‍යශීලී පටකයකින්ද?", "ප්‍රත්‍යාස්ථ කෘචස්ථිය (Elastic Cartilage)", "හයලින් කෘචස්ථිය", "ඝන අස්ථි පටකය", "සැකිලි පේශිය", "ප්‍රත්‍යාස්ථ කෘචස්ථියේ ඉලාස්ටින් බහුල බැවින් නැවීමට හා පෙර හැඩය ගැනීමට හැකියාව ඇත."),
        q("ආහාර ගිලින අවස්ථාවේදී ශ්වාසනාලයට ආහාර හෝ ජලය ඇතුළු වීම වළක්වන පියන වැනි කාටිලේජමය ව්‍යුහය කුමක්ද?", "උපජිහ්විකාව හෙවත් එපිග්ලොටිසය (Epiglottis)", "ස්වරාලය", "දිව", "තල්ල", "ගිලීමේදී එපිග්ලොටිසය මගින් ස්වරාලයේ විවරය (ග්ලොටිසය) ආවරණය කරයි."),
        q("මිනිස් ශ්වාසනාලය බිඳවැටීම (හැකිලීම) වළක්වමින් නිතර විවෘතව තබාගැනීමට පිහිටා ඇති ව්‍යුහ මොනවාද?", "'C' හැඩැති කෘචස්ථි වළලු", "අස්ථි මුදු", "පේශි පටක පමණක්", "බන්ධනී පටල", "C හැඩැති හයලින් කෘචස්ථි වළලු 16-20 ක් ශ්වාසනාලය දිගට පිහිටා වාතය ගමන් කිරීම සුරක්ෂිත කරයි."),
        q("පෙනහළුවල ඇති වායු කෝෂ (ඇල්වියෝල) හැකිලී යාම වැළැක්වීමට ඒවායේ ඇතුළත බිත්තියේ ඇති පෘෂ්ඨික ආතතිය අඩු කරන ලිපිඩමය ද්‍රව්‍යය කුමක්ද?", "සර්ෆැක්ටන්ට් (Surfactant)", "ශ්ලේෂ්මලය", "හිමොග්ලොබින්", "ප්ලාස්මාව", "සර්ෆැක්ටන්ට් මගින් වායු කෝෂවල බිත්ති එකට ඇලී යාම වළක්වා හුස්ම ගැනීම පහසු කරයි."),
        q("දීර්ඝ කාලයක් සිගරට් දුම්පානය කිරීම නිසා වායු කෝෂවල බිත්ති විනාශ වී හුස්ම ගැනීමේ අපහසුව ඇතිවන නිදන්ගත රෝගය කුමක්ද?", "එම්ෆයිසීමාව (Emphysema)", "ඇදුම", "ක්ෂය රෝගය", "නියුමෝනියාව", "එම්ෆයිසීමාවේදී පෙනහළුවල වායු හුවමාරු මතුපිට වර්ගඵලය බරපතළ ලෙස ක්ෂය වී යයි."),
        q("මිනිස් සිරුරේ බාහිරින්ම පිහිටි විශාලතම ඉන්ද්‍රිය වන සමෙහි ස්ථර දෙක මොනවාද?", "චර්මය (Dermis) සහ අපිචර්මය (Epidermis)", "පෙරියොස්ටියම සහ එන්ඩොස්ටියම", "ප්ලූරාව සහ පෙරිකාඩියම", "ශ්ලේෂ්මල සහ සේරස", "අපිචර්මය බාහිර ආරක්ෂිත ස්ථරය වන අතර චර්මය රුධිර නාල හා සංවේදක අඩංගු ගැඹුරු ස්ථරයයි."),
        q("සමේ අපිචර්මයේ පිහිටා ඇති, සමට සහ හිසකෙස්වලට වර්ණය ලබාදෙන වර්ණකය කුමක්ද?", "මෙලනින් (Melanin)", "කැරොටින්", "හිමොග්ලොබින්", "බිලිරුබින්", "මෙලනින් මගින් හිරු එළියේ ඇති හානිකර පාරජම්බුල (UV) කිරණවලින් ශරීර සෛල ආරක්ෂා කරයි."),
        q("සමේ ඇති දහඩිය ග්‍රන්ථි මගින් ශරීර උෂ්ණත්වය පාලනය කිරීමට අමතරව බැහැර කරන සුළු අපද්‍රව්‍ය මොනවාද?", "ජලය, ලවණ (NaCl) සහ ස්වල්ප යූරියා ප්‍රමාණයක්", "ග්ලූකෝස් පමණි", "ප්‍රෝටීන පමණි", "කාබන් ඩයොක්සයිඩ්", "දහඩිය වාෂ්පීභවනය මගින් තාපය පිටවන අතර යූරියා සුළු ප්‍රමාණයක්ද පිටවේ."),
        q("නිරෝගී මිනිස් දේහයේ රුධිරයේ සාමාන්‍ය ග්ලූකෝස් මට්ටම නිරාහාරව සිටින විට තිබිය යුතු ප්‍රශස්ත පරාසය කුමක්ද?", "රුධිරය 100ml කට මිලිග්‍රෑම් 70 සිට 100 දක්වා (70-100 mg/dL)", "රුධිරය 100ml කට මිලිග්‍රෑම් 150 සිට 200 දක්වා", "රුධිරය 100ml කට මිලිග්‍රෑම් 200 ට වැඩි", "රුධිරය 100ml කට මිලිග්‍රෑම් 20 සිට 40 දක්වා", "නිරාහාර ග්ලූකෝස් මට්ටම 100 mg/dL ට අඩුවෙන් පැවතීම නිරෝගී තත්ත්වයකි."),
        q("මිනිස් සිරුරේ රුධිරයේ සාමාන්‍ය pH අගය නිවැරදිව දැක්වෙන මඳ භෂ්මීය පරාසය කුමක්ද?", "7.35 සිට 7.45 දක්වා", "6.0 සිට 6.5 දක්වා", "8.5 සිට 9.0 දක්වා", "5.0 සිට 5.5 දක්වා", "රුධිරයේ pH අගය 7.35-7.45 අතර ඉතා පටු පරාසයක බෆර පද්ධති මගින් නියතව පාලනය වේ."),
        q("රුධිරය කැටි ගැසීමේ ස්වාභාවික ක්‍රියාවලියේදී අවසානයේ සෑදෙන දිය නොවන තන්තුමය දැල කුමක්ද?", "ෆයිබ්‍රින් (Fibrin)", "ෆයිබ්‍රිනොජන්", "ප්‍රෝත්‍රොම්බින්", "ඇල්බියුමින්", "ත්‍රොම්බින් එන්සයිමය මගින් ප්ලාස්මාවේ ඇති ෆයිබ්‍රිනොජන් දිය නොවන ෆයිබ්‍රින් තන්තු බවට පත් කරයි."),
        q("රුධිර නාලයක අභ්‍යන්තර බිත්තියට හානි නොවී රුධිරය කැටි ගැසීම වැළැක්වීම සඳහා ශරීරය තුළ ස්වාභාවිකව නිපදවෙන ප්‍රතිස්කන්ධකය කුමක්ද?", "හෙපරින් (Heparin)", "ෆයිබ්‍රින්", "හිස්ටමින්", "ඇසිටයිල්කොලීන්", "හෙපරින් මගින් රුධිර සංසරණ පද්ධතිය තුළ රුධිරය කැටි ගැසීමකින් තොරව නිදහසේ ගලායාමට සලස්වයි."),
        q("අක්මාව මගින් නිෂ්පාදනය කරනු ලබන රුධිර ප්ලාස්මාවේ ප්‍රධානතම ප්‍රෝටීන ත්‍රිත්වය මොනවාද?", "ඇල්බියුමින්, ග්ලොබියුලින් සහ ෆයිබ්‍රිනොජන්", "ඇක්ටින්, මයොසින් සහ කොලැජන්", "කෙරටින්, ඉලාස්ටින් සහ සෙලියුලෝස්", "ඉන්සියුලින්, තයිරොක්සින් සහ පෙප්සින්", "ඇල්බියුමින් අවිකල පීඩනයද ග්ලොබියුලින් ප්‍රතිශක්තියද ෆයිබ්‍රිනොජන් රුධිර කැටිගැසීමද සිදු කරයි."),
        q("මිනිස් සිරුරේ අස්ථි වර්ධනය වන දිගු අස්ථිවල කෙළවර පිහිටි කාටිලේජමය කලාපය හඳුන්වන්නේ කෙසේද?", "එපිෆයිසීය තැටිය හෙවත් වර්ධක තැටිය (Epiphyseal Plate)", "පෙරියොස්ටියම", "සාර්කොමියරය", "සයිනෝවියල් මඬල", "නව යොවුන් විය අවසානයේ එපිෆයිසීය තැටිය අස්ථිභවනය වී උස යාම ස්ථිරවම නතර වේ."),
        q("මිනිසාගේ කශේරුකා තීරුවේ ස්වාභාවිකව පිහිටා ඇති වක්‍රතා සංඛ්‍යාව කීයද?", "වක්‍රතා 4කි (ග්‍රීව, උරස්, කටී සහ ත්‍රිකාස්ථි)", "වක්‍රතා 2කි", "වක්‍රතා 1කි", "වක්‍රතා 8කි", "මෙම වක්‍රතා සිරුරේ බර සමබරව දැරීමට සහ ඇවිදීමේදී කම්පන අවශෝෂණය කිරීමට උපකාරී වේ."),
        q("ක්‍රීඩා පුහුණුව නිසා පෙනහළුවල වායු හුවමාරු කාර්යක්ෂමතාව ඉහළ යාමට ප්‍රධාන හේතුව කුමක්ද?", "පෙනහළු වායු කෝෂ වටා ඇති රුධිර කේශනාලිකා ඝනත්වය සහ ක්‍රියාකාරී වායු කෝෂ ප්‍රමාණය වැඩිවීම", "පෙනහළු කුඩා වීම", "ශ්වාසනාලය පටු වීම", "ශ්වසන වේගය අඩුවීම පමණි", "ක්‍රමානුකූල පුහුණුව මගින් රුධිරයට ඔක්සිජන් විසරණය වීමේ ධාරිතාව බෙහෙවින් ඉහළ නංවයි."),
        q("මිනිස් සිරුරේ සාමාන්‍යයෙන් රුධිර පරිමාව ශරීර බරෙන් කොපමණ ප්‍රතිශතයක් නියෝජනය කරයිද?", "ශරීර බරෙන් 7% සිට 8% දක්වා (ලීටර් 5ක් පමණ)", "ශරීර බරෙන් 25%ක්", "ශරීර බරෙන් 50%ක්", "ශරීර බරෙන් 1%ක්", "සාමාන්‍ය වැඩිහිටියෙකු තුළ රුධිරය ලීටර් 4.5 සිට 5.5 දක්වා ප්‍රමාණයක් අඩංගු වේ."),
        q("වකුගඩු අකර්මණ්‍ය වූ රෝගියෙකුගේ රුධිරයේ ඇති අපද්‍රව්‍ය ඉවත් කිරීම සඳහා යොදාගන්නා කෘත්‍රිම ප්‍රතිකාර ක්‍රමය කුමක්ද?", "රුධිර කාන්දු පෙරණය (Haemodialysis)", "ස්පයිරෝමෙට්‍රිය", "ECG පරීක්ෂාව", "එන්ඩොස්කොපිය", "ඩයලයිසිස් යන්ත්‍රයක් මගින් අර්ධ පාරගම්‍ය පටලයක් හරහා යූරියා සහ අතිරික්ත ලවණ රුධිරයෙන් ඉවත් කරයි."),
        q("මිනිස් සිරුරේ බරින් වැඩිම ප්‍රමාණයක් දරන අක්ෂක ඇටසැකිල්ලේ කශේරුකා කලාපය කුමක්ද?", "කටී කශේරුකා කලාපය (Lumbar Region)", "ග්‍රීව කලාපය", "උරස් කලාපය", "අනුත්‍රිකාස්ථි කලාපය", "කටී කශේරුකා ශරීරයේ ඉහළ බර සම්පූර්ණයෙන්ම ශ්‍රෝණිය වෙත සම්ප්‍රේෂණය කරන බැවින් විශාලව පිහිටයි."),
        q("මිනිස් සිරුරේ මාංශපේශී හැකිලීමේදී ඇතිවන චාලක ශක්තියට අමතරව නිපදවෙන අතුරු ඵලය කුමක්ද?", "ශරීර උෂ්ණත්වය පවත්වා ගැනීමට අවශ්‍ය තාපය", "විදුලිය පමණි", "ජලය පමණි", "ආලෝකය", "පේශි හැකිලීමේදී වැයවන ශක්තියෙන් 60-70%ක් පමණ තාපය ලෙස මුදාහැරී ශරීර උෂ්ණත්වය පවත්වා ගනී."),
        q("වෙව්ලීම (Shivering) මගින් සීතල පරිසරයකදී ශරීරයට සිදුවන යහපත් කායික විද්‍යාත්මක ප්‍රතිඵලය කුමක්ද?", "සැකිලි පේශි වේගයෙන් හැකිලීම මගින් අමතර තාපය නිපදවීම", "රුධිර පීඩනය අඩු කිරීම", "ශරීරයෙන් ජලය ඉවත් කිරීම", "නින්ද ළඟා කරදීම", "අනෛච්ඡිකව සිදුවන ක්ෂණික පේශි හැකිලීම් මගින් පරිවෘත්තීය තාපය නිපදවා ශරීර උෂ්ණත්වය ඉහළ නංවයි.")
    )
}
